package streamworkspace_test

import (
	"context"
	"fmt"
	"testing"

	"github.com/hashicorp/terraform-plugin-testing/helper/resource"
	"github.com/hashicorp/terraform-plugin-testing/terraform"

	"github.com/mongodb/terraform-provider-mongodbatlas/internal/testutil/acc"
	"github.com/mongodb/terraform-provider-mongodbatlas/internal/testutil/mig"
)

// Migration test for the autogenerated mongodbatlas_stream_workspace (spike pilot,
// no-change group): the config syntax is identical under the manual and autogen
// implementations (both TPF assignment syntax), so the migration must plan EMPTY at
// the same address: no accepted diffs, no replacement.

const (
	migResourceName = "mongodbatlas_stream_workspace.test"
	migRegion       = "VIRGINIA_USA"
	migCloudProvide = "AWS"
)

func TestMigStreamWorkspace_basic(t *testing.T) {
	var (
		projectID     = acc.ProjectIDExecution(t)
		workspaceName = acc.RandomName()
		// Same config for both implementations: no config rewrite in this migration.
		config = migConfig(projectID, workspaceName)
	)

	resource.ParallelTest(t, resource.TestCase{
		PreCheck:     func() { mig.PreCheckBasic(t) },
		CheckDestroy: checkMigDestroy,
		Steps: []resource.TestStep{
			{
				// Step 1: the released provider (manual implementation) creates the workspace.
				ExternalProviders: mig.ExternalProviders(),
				Config:            config,
				Check: resource.ComposeAggregateTestCheckFunc(
					checkMigExists(projectID, workspaceName),
					resource.TestCheckResourceAttr(migResourceName, "project_id", projectID),
					resource.TestCheckResourceAttr(migResourceName, "workspace_name", workspaceName),
					resource.TestCheckResourceAttr(migResourceName, "data_process_region.region", migRegion),
					resource.TestCheckResourceAttr(migResourceName, "stream_config.tier", "SP10"),
				),
			},
			{
				// Step 2: the autogen implementation must plan no diff at the same address.
				Config:                   config,
				ProtoV6ProviderFactories: acc.TestAccProviderV6Factories,
				PlanOnly:                 true,
				ExpectNonEmptyPlan:       false,
			},
		},
	})
}

func migConfig(projectID, workspaceName string) string {
	return fmt.Sprintf(`
		resource "mongodbatlas_stream_workspace" "test" {
			project_id     = %[1]q
			workspace_name = %[2]q
			data_process_region = {
				region         = %[3]q
				cloud_provider = %[4]q
			}
			stream_config = {
				tier = "SP10"
			}
		}
	`, projectID, workspaceName, migRegion, migCloudProvide)
}

func checkMigExists(projectID, workspaceName string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[migResourceName]
		if !ok {
			return fmt.Errorf("not found: %s", migResourceName)
		}
		if rs.Primary.ID == "" {
			return fmt.Errorf("no ID is set")
		}
		_, _, err := acc.ConnV2().StreamsAPI.GetStreamWorkspace(context.Background(), projectID, workspaceName).Execute()
		if err != nil {
			return fmt.Errorf("stream workspace (%s:%s) does not exist: %s", projectID, workspaceName, err)
		}
		return nil
	}
}

func checkMigDestroy(s *terraform.State) error {
	for _, rs := range s.RootModule().Resources {
		if rs.Type != "mongodbatlas_stream_workspace" {
			continue
		}
		projectID := rs.Primary.Attributes["project_id"]
		workspaceName := rs.Primary.Attributes["workspace_name"]
		_, _, err := acc.ConnV2().StreamsAPI.GetStreamWorkspace(context.Background(), projectID, workspaceName).Execute()
		if err == nil {
			return fmt.Errorf("stream workspace (%s) still exists", rs.Primary.ID)
		}
	}
	return nil
}
